"use client"

import * as React from "react"
import JournalSpreadCarousel, { type JournalSpread } from "@/components/ui/journal-spread-carousel"

// Free Unsplash photos of Lisbon, Sintra, Aveiro and the Algarve, packed into two AVIF
// sheets so the demo fetches nothing off-origin. They are cut back into separate
// same-origin images on load. In your app, pass plain image URLs instead.
//
// Spread sheet (2 x 4 tiles, 640 x 512), unsplash.com/photos/<id>:
//   1665091982331-e66db14feae6, 1559315542-780c225b5239, 1565865735988-fd5752a02846, 1486571698588-a2204703bec8
//   1559163806-3ca824710bf8, 1531772337062-9d94547f333f, 1526737511523-ba685f246e8c, 1525155000528-d926bd2a3755
// Print sheet (4 x 4 tiles, 180 x 225):
//   1562250883-5b8fa0be26ab, 1582407672718-3429c4b2c39d, 1791719229657-ec16750a5a2d, 1562195168-c82fea0f0953
//   1751808862930-d839da90d0e1, 1721639713587-f4ae92bba42f, 1536663205865-cc64102c5e0d, 1562762562-8670c946876c
//   1548884642-f00c2df80668, 1769013556856-e70c58c9db8a, 1650557175315-05ad335468f2, 1608649944716-228404a0a8bb
//   1655986406308-bfa317b6302b, 1649257701313-be3fb439987d, 1712581566227-1e5277055cac, 1660403269439-383de3c8e3cc
const SPREAD_SHEET = "data:image/avif;base64,"
const PRINT_SHEET = "data:image/avif;base64,"

function useSheetTiles(src: string, cols: number, rows: number) {
  const [tiles, setTiles] = React.useState(null as string[] | null)
  React.useEffect(() => {
    let alive = true
    const made = [] as string[]
    const img = new Image()
    img.src = src
    img
      .decode()
      .then(async () => {
        const w = img.naturalWidth / cols
        const h = img.naturalHeight / rows
        // One canvas per tile so the encodes run side by side.
        const blobs = await Promise.all(
          Array.from({ length: cols * rows }, (_, i) => {
            const c = document.createElement("canvas")
            c.width = w
            c.height = h
            c.getContext("2d")?.drawImage(img, (i % cols) * w, Math.floor(i / cols) * h, w, h, 0, 0, w, h)
            return new Promise((r: (b: Blob | null) => void) => c.toBlob(r, "image/jpeg", 0.92))
          }),
        )
        blobs.forEach((b) => made.push(b ? URL.createObjectURL(b) : ""))
        if (alive) setTiles(made)
      })
      .catch(() => {})
    return () => {
      alive = false
      made.forEach((u) => URL.revokeObjectURL(u))
    }
  }, [src, cols, rows])
  return tiles
}

function build(bg: string[], pr: string[]): JournalSpread[] {
  return [
    {
      label: "Lisbon, day one",
      image: bg[0],
      alt: "A yellow tram climbing a cobbled Lisbon street",
      prints: [{ src: pr[0], x: 5, y: 9, w: 21, rotate: -7, caption: "tram 28 :)" }],
      notes: [{ x: 28, y: 63, w: 22, rotate: 2, title: "Day one", body: "Missed our stop twice. Worth it." }],
    },
    {
      label: "Algarve cliffs",
      image: bg[1],
      alt: "Golden sea stacks over a turquoise cove",
      prints: [
        { src: pr[2], x: 72, y: 50, w: 21, rotate: 6, caption: "the boys, 9am" },
        { src: pr[11], x: 6, y: 56, w: 21, rotate: -4, tape: true },
      ],
      notes: [{ x: 7, y: 7, w: 42, style: "ink", title: "Algarve", body: "Saltwater hair for a week straight." }],
    },
    {
      label: "Sintra",
      image: bg[2],
      alt: "A yellow and red palace above a green forest",
      prints: [{ src: pr[3], x: 70, y: 8, w: 21, rotate: 5, caption: "31° in the shade" }],
      notes: [{ x: 6, y: 9, w: 27, rotate: -2, title: "Pena Palace", body: "Yellow, red, and somehow it works." }],
    },
    {
      label: "Beach day",
      image: bg[3],
      alt: "A crowded sandy beach under a blue sky",
      prints: [
        { src: pr[4], x: 6, y: 48, w: 21, rotate: -5, caption: "golden hour" },
        { src: pr[5], x: 74, y: 52, w: 19, rotate: 7, tape: true },
      ],
      notes: [{ x: 32, y: 8, w: 44, style: "ink", title: "Praia day", body: "SPF 50. Still burnt." }],
    },
    {
      label: "Pink Street",
      image: bg[4],
      alt: "A pink-painted street under a yellow arch",
      prints: [
        { src: pr[6], x: 72, y: 7, w: 21, rotate: 6, caption: "Pink Street" },
        { src: pr[7], x: 74, y: 54, w: 19, rotate: -5, tape: true },
      ],
      notes: [{ x: 5, y: 68, w: 26, rotate: -3, title: "Cais do Sodré", body: "Dancing till the trams stopped." }],
    },
    {
      label: "Aveiro",
      image: bg[5],
      alt: "Painted houses along a canal",
      prints: [
        { src: pr[8], x: 5, y: 52, w: 21, rotate: -6, caption: "Porto by boat" },
        { src: pr[9], x: 75, y: 50, w: 19, rotate: 5, tape: true },
      ],
      notes: [{ x: 30, y: 4, w: 44, style: "ink", title: "Aveiro", body: "Painted boats and ovos moles." }],
    },
    {
      label: "The cove",
      image: bg[6],
      alt: "Turquoise water and rocks seen from above",
      prints: [{ src: pr[10], x: 7, y: 10, w: 22, rotate: -5, caption: "secret cove" }],
      notes: [{ x: 64, y: 62, w: 28, rotate: 2, title: "From above", body: "Climbed down 212 steps. Climbed up 212 steps." }],
    },
    {
      label: "Alfama",
      image: bg[7],
      alt: "A woman leaning on a yellow wall by tram tracks",
      prints: [
        { src: pr[12], x: 73, y: 7, w: 20, rotate: 5, caption: "Tavira" },
        { src: pr[13], x: 74, y: 52, w: 19, rotate: -4, tape: true },
      ],
      notes: [{ x: 5, y: 8, w: 26, rotate: -2, title: "Alfama", body: "Every street is a staircase." }],
    },
    {
      label: "Last page",
      paper: "#efe8da",
      prints: [
        { src: pr[14], x: 7, y: 9, w: 23, rotate: -4, caption: "last morning" },
        { src: pr[15], x: 31, y: 44, w: 21, rotate: 5, caption: "night walk" },
        { src: pr[1], x: 58, y: 8, w: 20, rotate: 3, tape: true },
      ],
      notes: [{ x: 60, y: 60, w: 31, rotate: -2, title: "Até já, Lisboa", body: "Twelve days, one very full journal." }],
    },
  ]
}

export default function Demo() {
  const bg = useSheetTiles(SPREAD_SHEET, 2, 4)
  const pr = useSheetTiles(PRINT_SHEET, 4, 4)
  const spreads = React.useMemo(() => (bg && pr ? build(bg, pr) : null), [bg, pr])
  if (!spreads) return <div style={{ width: "100%", height: "100svh", background: "#363b58" }} />
  return <JournalSpreadCarousel spreads={spreads} title="Summer Journal" initialIndex={3} />
}
